import{_ as s,C as o,c as i,o as r,ae as a,G as l}from"./chunks/framework.DI6M9D4h.js";const h="/assets/plaid-pad-1N4148-diodes-1.J_16ze_m.jpg",p="/assets/plaid-pad-zener-diodes-1.CAU-MCit.jpg",d="/assets/plaid-pad-resettable-fuse-1.C4FQgasg.jpg",n="/assets/plaid-pad-electrolytic-capacitor-1.B6O0EpPo.jpg",c="/assets/plaid-pad-resistors-1.5k-1.CQhc_rtq.jpg",m="/assets/plaid-pad-resistors-1.5k-2.uXdx5GXI.jpg",u="/assets/plaid-pad-resistors-75-1.jX0gq2gv.jpg",g="/assets/plaid-pad-resistors-10k-1.DKi5Gbkd.jpg",b="/assets/plaid-pad-resistors-5.1k-1.DeoE6eat.jpg",k="/assets/plaid-pad-usb-c-connector-1.BtrTxrkO.jpg",f="/assets/plaid-pad-leds-1.WSQRZM5u.jpg",y="/assets/plaid-pad-crystal-1.DjhPyQsQ.jpg",w="/assets/plaid-pad-capacitors-22pf-1.BKwVnyFH.jpg",_="/assets/plaid-pad-capacitors-0.1uf-1.4bpKchWb.jpg",C="/assets/plaid-pad-ic-socket-1.CxKEGHwD.jpg",P="/assets/plaid-pad-tactile-switch-1.Df0z-zaZ.jpg",q="/assets/plaid-pad-atmega329p-1.BqlGwmzP.jpg",x="/assets/plaid-pad-oled-ssd1306-1.CEQUv-Q5.jpg",v="/assets/plaid-pad-oled-ssd1306-2.DIo6eMDr.jpg",B="/assets/plaid-pad-tweezers-switch-test-1.uYuuc0qh.jpg",F="/assets/plaid-pad-mill-max-0305-holtite-2.B-WPcFTa.jpg",T="/assets/plaid-pad-mill-max-0305-holtite-3.DjfP6Nce.jpg",E="/assets/plaid-pad-top-plate-1.BwrkHJLh.jpg",D="/assets/plaid-pad-top-plate-2.CwTeBsIW.jpg",R="/assets/plaid-pad-top-plate-3.Bpgmhwcu.jpg",S="/assets/rotary-encoder-pin-adjustment-1.C8iyVyCd.jpg",z="/assets/plaid-pad-top-plate-4.DkV6sA--.jpg",A="/assets/plaid-pad-bottom-plate-1.DT0eYeLP.jpg",O="/assets/plaid-pad-bottom-plate-2.Df7EEGxu.jpg",j="/assets/plaid-pad-final-1.BrqqZOSU.jpg",G=JSON.parse('{"title":"Build guide for the Plaid-Pad","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/plaid-pad/index.md","filePath":"build-guides/plaid-pad/index.md","lastUpdated":1756808138000}'),I={name:"build-guides/plaid-pad/index.md"};function M(L,e,K,U,V,Q){const t=o("YouTubeEmbed");return r(),i("div",null,[e[0]||(e[0]=a('<h1 id="build-guide-for-the-plaid-pad" tabindex="-1">Build guide for the Plaid-Pad <a class="header-anchor" href="#build-guide-for-the-plaid-pad" aria-label="Permalink to &quot;Build guide for the Plaid-Pad&quot;">​</a></h1><h2 id="solder-the-through-hole-parts" tabindex="-1">Solder the through hole parts <a class="header-anchor" href="#solder-the-through-hole-parts" aria-label="Permalink to &quot;Solder the through hole parts&quot;">​</a></h2><h3 id="diodes-1n4148-d1-d16" tabindex="-1">Diodes 1N4148 (D1-D16) <a class="header-anchor" href="#diodes-1n4148-d1-d16" aria-label="Permalink to &quot;Diodes 1N4148 (D1-D16)&quot;">​</a></h3><p>Diodes are <strong>polarized</strong>. The black line on the diode (cathode) must face the squared solder pad. The 1N4148 diodes look similar as Zener diodes - so make sure that you don&#39;t confuse both diodes.</p><p>You can use some tape, as show in the image, to hold the diodes in place and solder all in one pass.</p><p><img src="'+h+'" alt="alt" loading="lazy"></p><h3 id="zener-diodes-d49-d50" tabindex="-1">Zener diodes (D49, D50) <a class="header-anchor" href="#zener-diodes-d49-d50" aria-label="Permalink to &quot;Zener diodes (D49, D50)&quot;">​</a></h3><p>The diodes are <strong>polarized</strong> where the black line on the diode (cathode) must face the squared solder pad. The 1N4148 diodes look similar as Zener diodes - so make sure that you don&#39;t confuse both diodes.</p><p><img src="'+p+'" alt="alt" loading="lazy"></p><h3 id="resettable-fuse-f1" tabindex="-1">Resettable fuse (F1) <a class="header-anchor" href="#resettable-fuse-f1" aria-label="Permalink to &quot;Resettable fuse (F1)&quot;">​</a></h3><p>Attach and solder the fuse to <code>F1</code>. After soldering, bend the fuse like in the image.</p><p><img src="'+d+'" alt="alt" loading="lazy"></p><h3 id="electrolytic-capacitor-c3" tabindex="-1">Electrolytic capacitor (C3) <a class="header-anchor" href="#electrolytic-capacitor-c3" aria-label="Permalink to &quot;Electrolytic capacitor (C3)&quot;">​</a></h3><p>The Electrolytic capacitor is <strong>polarized</strong>. The short leg is cathode which needs to be attached to the square pad on the PCB.</p><p><img src="'+n+'" alt="alt" loading="lazy"></p><h3 id="resistors-1-5k-ohm-r1-r7" tabindex="-1">Resistors 1.5k Ohm (R1, R7) <a class="header-anchor" href="#resistors-1-5k-ohm-r1-r7" aria-label="Permalink to &quot;Resistors 1.5k Ohm (R1, R7)&quot;">​</a></h3><p>Attach the resistors with following colors from left to right:</p><ul><li>brown, green, black, brown, brown</li></ul><p><img src="'+c+'" alt="alt" loading="lazy"> <img src="'+m+'" alt="alt" loading="lazy"></p><h3 id="resistors-75-ohm-r2-r3" tabindex="-1">Resistors 75 Ohm (R2, R3) <a class="header-anchor" href="#resistors-75-ohm-r2-r3" aria-label="Permalink to &quot;Resistors 75 Ohm (R2, R3)&quot;">​</a></h3><p>Attach the resistors with following colors from left to right:</p><ul><li>brown, gold, black, green, purple</li></ul><p><img src="'+u+'" alt="alt" loading="lazy"></p><h3 id="resistors-10k-ohm-r4" tabindex="-1">Resistors 10k Ohm (R4) <a class="header-anchor" href="#resistors-10k-ohm-r4" aria-label="Permalink to &quot;Resistors 10k Ohm (R4)&quot;">​</a></h3><p>Attach the resistors with following colors from left to right:</p><ul><li>brown, black, black, red, brown</li></ul><p><img src="'+g+'" alt="alt" loading="lazy"></p><h3 id="resistors-5-1k-ohm-r8-r9" tabindex="-1">Resistors 5.1k Ohm (R8, R9) <a class="header-anchor" href="#resistors-5-1k-ohm-r8-r9" aria-label="Permalink to &quot;Resistors 5.1k Ohm (R8, R9)&quot;">​</a></h3><p>Attach the resistors with following colors from left to right:</p><ul><li>green, brown, black, brown, brown</li></ul><p><img src="'+b+'" alt="alt" loading="lazy"></p><h3 id="usb-c-connector-j1" tabindex="-1">USB-C connector (J1) <a class="header-anchor" href="#usb-c-connector-j1" aria-label="Permalink to &quot;USB-C connector (J1)&quot;">​</a></h3><p>Double check that there are no short cuts between the solder pads. A magnifier is handy for this task.</p><p><img src="'+k+'" alt="alt" loading="lazy"></p><h3 id="optional-led-led1" tabindex="-1">Optional: LED (LED1) <a class="header-anchor" href="#optional-led-led1" aria-label="Permalink to &quot;Optional: LED (LED1)&quot;">​</a></h3><p>The LEDs are <strong>polarized</strong>. The short leg is the cathode which needs to be attached to the square pad on the PCB</p><p><code>LED1</code> indicates that the Plaid-Pad is powered and constantly on.</p><p>If you don&#39;t want a constant red light on your Plaid-Pad, don&#39;t solder this LED.</p><p><img src="'+f+'" alt="alt" loading="lazy"></p><h3 id="crystal-y1" tabindex="-1">Crystal (Y1) <a class="header-anchor" href="#crystal-y1" aria-label="Permalink to &quot;Crystal (Y1)&quot;">​</a></h3><p><img src="'+y+'" alt="alt" loading="lazy"></p><h3 id="capacitors-22pf-c1-c2" tabindex="-1">Capacitors 22pF (C1, C2) <a class="header-anchor" href="#capacitors-22pf-c1-c2" aria-label="Permalink to &quot;Capacitors 22pF (C1, C2)&quot;">​</a></h3><p>They have a small pitch (2.5mm).</p><p><img src="'+w+'" alt="alt" loading="lazy"></p><h3 id="capacitors-0-1uf-c4-c5" tabindex="-1">Capacitors 0.1uF (C4, C5) <a class="header-anchor" href="#capacitors-0-1uf-c4-c5" aria-label="Permalink to &quot;Capacitors 0.1uF (C4, C5)&quot;">​</a></h3><p>These have a larger pitch of 5mm.</p><p><img src="'+_+'" alt="alt" loading="lazy"></p><h3 id="ic-socket-u1" tabindex="-1">IC socket U1 <a class="header-anchor" href="#ic-socket-u1" aria-label="Permalink to &quot;IC socket U1&quot;">​</a></h3><p>The IC socket is <strong>polarized</strong>. Check the notch on the silk and the IC Socket.</p><p><img src="'+C+'" alt="alt" loading="lazy"></p><h3 id="tactile-switch-sw50-reset-sw51-boot" tabindex="-1">Tactile switch (SW50/RESET, SW51/BOOT) <a class="header-anchor" href="#tactile-switch-sw50-reset-sw51-boot" aria-label="Permalink to &quot;Tactile switch (SW50/RESET, SW51/BOOT)&quot;">​</a></h3><p><img src="'+P+'" alt="alt" loading="lazy"></p><h3 id="atmega328p-chip" tabindex="-1">ATMEGA328p chip <a class="header-anchor" href="#atmega328p-chip" aria-label="Permalink to &quot;ATMEGA328p chip&quot;">​</a></h3><p>The ATMEGA328 has to be attached in a <strong>specific direction</strong>. Check the notch on the chip and IC Socket - they need to match. Here, the notch faces the crystal at <code>Y1</code>.</p><p><img src="'+q+'" alt="alt" loading="lazy"></p><h3 id="optional-oled-display-ssd1306" tabindex="-1">Optional OLED display (SSD1306) <a class="header-anchor" href="#optional-oled-display-ssd1306" aria-label="Permalink to &quot;Optional OLED display (SSD1306)&quot;">​</a></h3><p>Add isolation tape to the back of the OLED, to protect the components for shorts.</p><p><img src="'+x+'" alt="alt" loading="lazy"></p><p>Place the OLED like on the image and solder it from the bottom to the PCB.</p><p><img src="'+v+'" alt="alt" loading="lazy"></p><h2 id="check-list-before-connecting-usb" tabindex="-1">Check list before connecting USB <a class="header-anchor" href="#check-list-before-connecting-usb" aria-label="Permalink to &quot;Check list before connecting USB&quot;">​</a></h2><ul><li>No short cuts on the USB-C connector pads</li><li>Direction of polarized and directional components is correct (ATMEGA328p, diode, resettable fuse, electrolytic capacitor, LEDs)</li><li>Resistors with correct values are attached to the target locations</li></ul><h2 id="test" tabindex="-1">Test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;Test&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Bootloader and Firmware (QMK VIAL) are already on the ATmega328P chip. Everything should work after soldering.</p></div><p>Connect the Plaid-Pad to your computer and open the <a href="https://config.qmk.fm/#/test" target="_blank" rel="noreferrer">QMK-Test-Site</a>.</p><p>Check whether all switches will work. To do so, short the solder pads with tweezers.</p><p><img src="'+B+'" alt="alt" loading="lazy"></p><h2 id="optional-mill-max-holtites" tabindex="-1">Optional Mill-Max holtites <a class="header-anchor" href="#optional-mill-max-holtites" aria-label="Permalink to &quot;Optional Mill-Max holtites&quot;">​</a></h2><p>The Plaid-Pad supports <a href="https://keycapsss.com/keyboard-parts/parts/73/mill-max-0305-holtite-for-switches-hotswap-sockets?number=KC10042_50x" target="_blank" rel="noreferrer">Mill-Max 0305 Holtites</a>. If these are installed, you can Hotswap the switches (change without soldering).</p><p>Put the holtite in the related holes.</p><p><img src="'+F+'" alt="alt" loading="lazy"></p><p>Install all switches to the top plate. Check that all switch pins are straight and press the top plate with switches on the PCB with the holtites.</p><p>Pay attention that no solder flows into the holtite.</p><p><img src="'+T+'" alt="alt" loading="lazy"></p><h2 id="case-assembly" tabindex="-1">Case assembly <a class="header-anchor" href="#case-assembly" aria-label="Permalink to &quot;Case assembly&quot;">​</a></h2>',75)),l(t,{"video-id":"HQoExdTddxo"}),e[1]||(e[1]=a('<p><strong>Before you solder the switches,</strong> attach the 4x 5mm spacer to the pcb with the M2x4mm screws. <strong>Don&#39;t solder the rotary encoder yet.</strong></p><p><img src="'+E+'" alt="alt" loading="lazy"> <img src="'+D+'" alt="alt" loading="lazy"></p><p>Attach all switches to the top plate and place <strong>(not solder)</strong> the desired amount of the rotary encoder on the pcb (<a href="https://github.com/BenRoe/Plaid-Pad#keymap" target="_blank" rel="noreferrer">more information about rotary encoder placement</a>).</p><p><img src="'+R+'" alt="alt" loading="lazy"></p><p>This way the rotary encoder have room to move and fit perfect into the top plate cutout.</p><h3 id="rotary-encoder-and-choc-low-profile-switches-skip-if-you-use-mx-switches" tabindex="-1">Rotary encoder and Choc (low profile) switches (skip if you use MX switches) <a class="header-anchor" href="#rotary-encoder-and-choc-low-profile-switches-skip-if-you-use-mx-switches" aria-label="Permalink to &quot;Rotary encoder and Choc (low profile) switches (skip if you use MX switches)&quot;">​</a></h3><p>If you use Choc (low profile) switches, you have to bend the 5 pins of the rotary encoder with a pliers, to fit into the top plate.</p><p><img src="'+S+'" alt="alt" loading="lazy"></p><hr><p>Put the top plate with the switches on the front side of the pcb. Solder the switches and rotary encoder from the bottom side. <strong>Ensure that there is no gap between the switch bottom and the pcb. Same for the encoder.</strong></p><p><img src="'+z+'" alt="alt" loading="lazy"></p><p>Screw the 4x 5mm spacer at the upper part of the bottom plate. Use the 12mm (10mm) screws for it.</p><p><img src="'+A+'" alt="alt" loading="lazy"></p><p>Optional: Put the dampening foam on the bottom plate.</p><p><img src="'+O+'" alt="alt" loading="lazy"></p><p>Put the assembled top plate with the switches and pcb on the bottom plate.</p><p>Screw the 4x 10mm spacer for the guard plate on 12mm (10mm) prominent screws from below. Remove the protection film on both sides from the acrylic guard plate. Fix the acrylic guard plate and the pcb with the 4mm screws.</p><p><strong>Don&#39;t overtighten the screws, the acrylic plate can break.</strong></p><p><img src="'+j+'" alt="alt" loading="lazy"></p><p>Put the rubber feeds on the back of the Plaid-Pad.</p><p><strong>The assembly is done.</strong> 🥳</p><p>You can change the keymap with <a href="https://get.vial.today" target="_blank" rel="noreferrer">VIAL</a>, or change the <a href="https://github.com/BenRoe/Plaid-Pad#qmk-default-keymap" target="_blank" rel="noreferrer">QMK keymap</a> file and reflash the firmware.</p><h2 id="how-to-flash-the-firmware" tabindex="-1">How to flash the firmware <a class="header-anchor" href="#how-to-flash-the-firmware" aria-label="Permalink to &quot;How to flash the firmware&quot;">​</a></h2><h3 id="qmk-with-vial-support-support-for-rotary-encoder" tabindex="-1">QMK with VIAL support (support for rotary encoder) <a class="header-anchor" href="#qmk-with-vial-support-support-for-rotary-encoder" aria-label="Permalink to &quot;QMK with VIAL support (support for rotary encoder)&quot;">​</a></h3><p><em>Plaid-Pad Kit&#39;s Rev3 shipped with preflashed VIAL firmware.</em></p><p>If you have a Rev2 Plaid-Pad, or want to re-flash the VIAL firmware again, you can find a compiled firmware file here (<a href="./[keycapsss_plaid_pad_rev2_vial.hex](https://minhaskamal.github.io/DownGit/#/home?url=https://github.com/Keycapsss/Plaid-Pad/blob/master/keycapsss_plaid_pad_rev2_vial.hex)">Rev2</a>, <a href="./[keycapsss_plaid_pad_rev3_vial.hex](https://minhaskamal.github.io/DownGit/#/home?url=https://github.com/Keycapsss/Plaid-Pad/blob/master/keycapsss_plaid_pad_rev3_vial.hex)">Rev3</a>)</p><ol><li>Flash pre-compiled firmware on the Plaid-Pad with <a href="https://github.com/qmk/qmk_toolbox/releases" target="_blank" rel="noreferrer">QMK Toolbox</a> (<a href="#enter-bootloader-mode-to-flash-a-new-firmware">How to enter Bootloader Mode</a>).</li><li>Download the VIAL software from <a href="https://get.vial.today" target="_blank" rel="noreferrer">here</a></li><li>Connect the Plaid-Pad to the computer with a USB cable (Reconnect after flashing the firmware)</li><li>Open VIAL and change the keymap to your needs (automatic save)</li></ol><h3 id="qmk-with-via-support-no-rotary-encoder-support" tabindex="-1">QMK with VIA support (no rotary encoder support) <a class="header-anchor" href="#qmk-with-via-support-no-rotary-encoder-support" aria-label="Permalink to &quot;QMK with VIA support (no rotary encoder support)&quot;">​</a></h3><p>To use VIA, compile the VIA Keymap with the following command and flash it with <a href="https://github.com/qmk/qmk_toolbox/releases" target="_blank" rel="noreferrer">QMK Toolbox</a> on the Plaid-Pad (<a href="#enter-bootloader-mode-to-flash-a-new-firmware">enter Bootloader Mode</a>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qmk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> via</span></span></code></pre></div><ol><li>Download the VIA software from <a href="https://github.com/the-via/releases/releases/latest" target="_blank" rel="noreferrer">here</a></li><li>Connect the Plaid-Pad to the computer with a USB cable</li><li>Open VIA, switch to the <code>CONFIGURE</code> tab and change the keymap to your needs (automatic save)</li></ol><p><em>The current VIA version can&#39;t change the rotary encoder function.</em></p><h3 id="qmk-default-keymap" tabindex="-1">QMK Default Keymap <a class="header-anchor" href="#qmk-default-keymap" aria-label="Permalink to &quot;QMK Default Keymap&quot;">​</a></h3><p>Make example for this keyboard (after <a href="https://docs.qmk.fm/#/getting_started_build_tools" target="_blank" rel="noreferrer">setting up your build environment</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad:default</span></span></code></pre></div><p>or</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qmk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span></span></code></pre></div><p>Flashing example for this keyboard:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad:default:flash</span></span></code></pre></div><p>or</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qmk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span></span></code></pre></div><p>See the <a href="https://docs.qmk.fm/#/getting_started_build_tools" target="_blank" rel="noreferrer">build environment setup</a> and the <a href="https://docs.qmk.fm/#/getting_started_make_guide" target="_blank" rel="noreferrer">make instructions</a> for more information. Brand new to QMK? Start with the <a href="https://docs.qmk.fm/#/syllabus" target="_blank" rel="noreferrer">Complete Newbees Guide</a>.</p><p>You can find the rotary encoder code <a href="https://github.com/qmk/qmk_firmware/blob/95bbd799a4f86dac37fdf2354e008d2fed7f6660/keyboards/keycapsss/plaid_pad/keymaps/via/keymap.c#L71" target="_blank" rel="noreferrer">here</a>.</p><h2 id="bootloader" tabindex="-1">Bootloader <a class="header-anchor" href="#bootloader" aria-label="Permalink to &quot;Bootloader&quot;">​</a></h2><ul><li>same <code>usbasploader</code> as used for Plaid (<a href="https://github.com/hsgw/plaid/blob/master/doc/en/bootloader.md" target="_blank" rel="noreferrer">Instructions</a>, <a href="https://github.com/hsgw/USBaspLoader/tree/plaid" target="_blank" rel="noreferrer">Repository</a>)</li></ul><h3 id="enter-bootloader-mode-to-flash-a-new-firmware" tabindex="-1">Enter Bootloader Mode (to flash a new firmware) <a class="header-anchor" href="#enter-bootloader-mode-to-flash-a-new-firmware" aria-label="Permalink to &quot;Enter Bootloader Mode (to flash a new firmware)&quot;">​</a></h3><ul><li>Plug in the USB cable</li><li>Push and hold RESET switch</li><li>Push and hold BOOT switch</li><li>Release RESET switch</li><li>Release BOOT switch</li></ul><p>alternative method:</p><ul><li>Unplug the USB cable</li><li>Hold down the BOOT switch</li><li>Plug in the USB cable</li><li>Release the BOOT switch</li></ul><p>alternative method (<a href="https://docs.qmk.fm/#/feature_bootmagic?id=bootmagic-lite" target="_blank" rel="noreferrer">Bootmagic Lite</a>):</p><ul><li>Unplug the USB cable</li><li>Hold down the most top left key</li><li>Plug in the USB cable</li><li>Release the most top left key</li></ul><p>If you succeed to enter bootloader mode, you can see usbasp in device manager, or <code>*** USBAsp device connected</code> in <a href="https://github.com/qmk/qmk_toolbox" target="_blank" rel="noreferrer">QMK Toolbox</a>.</p>',52))])}const H=s(I,[["render",M]]);export{G as __pageData,H as default};
